# Node: research_planner (Research & Planning Agent)
execute_agent_research_planner() {
    log_step "🤖 Executing agent: Research & Planning Agent"

    # Prepare agent prompt
    local prompt_content
    read -r -d '' prompt_content << AGENT_PROMPT_EOF || true
You are a research and planning specialist.

Topic: $(get_var "USER_TOPIC" "research_planner")

Tasks:
1. Research the topic using web search (use firecrawl or web tools available)
2. Create $(get_var "MAX_PARTS" "research_planner") focused content sections
3. For each section, create a planning document with:
   - Research findings and key sources
   - Main points and arguments
   - Structural outline
   - Target word count (300-500 words per section)

Save research files to fixed directory: /tmp/flowsh_essay_work/
Required output files:
- /tmp/flowsh_essay_work/research_summary.md (overall findings)
- /tmp/flowsh_essay_work/Part_01.md (first section plan)
- /tmp/flowsh_essay_work/Part_02.md (second section plan)
{{#if (eq max_parts "3")}}
- /tmp/flowsh_essay_work/Part_03.md (third section plan)
{{/if}}

NOTE: Agents cannot set shell environment variables. Only create the specified files.

AGENT_PROMPT_EOF

    # Execute agent command
    local exit_code=0
    local agent_output=""

    # Execute with 180s timeout
    if command -v timeout >/dev/null 2>&1; then
        agent_output=$(timeout 180 opencode run "$prompt_content" 2>&1) || exit_code=$?
    else
        # Fallback for systems without timeout command
        agent_output=$(opencode run "$prompt_content" 2>&1) || exit_code=$?
    fi

    # Store agent execution results
    set_workflow_var "AGENT_RESEARCH_PLANNER_OUTPUT" "$agent_output"
    set_workflow_var "AGENT_RESEARCH_PLANNER_EXIT_CODE" "$exit_code"
    set_workflow_var "AGENT_RESEARCH_PLANNER_SUCCESS" "false"

    # Handle execution result
    if [[ $exit_code -eq 0 ]]; then
        set_workflow_var "AGENT_RESEARCH_PLANNER_SUCCESS" "true"
        log_success "Agent execution completed successfully"
        echo "$agent_output"
    else
        case $exit_code in
            124)
                log_error "Agent execution timed out after 180s"
                ;;
            127)
                log_error "Agent command not found: opencode"
                ;;
            *)
                log_error "Agent execution failed with exit code: $exit_code"
                ;;
        esac
        echo "$agent_output" >&2
    fi

    return $exit_code
}

